package main

import("context";"log";"os";"os/signal";"strconv";"strings";"syscall";"github.com/example-user/runnerhub/internal/agent";"github.com/example-user/runnerhub/internal/provider";dockerprovider "github.com/example-user/runnerhub/internal/providers/docker";firecrackerprovider "github.com/example-user/runnerhub/internal/providers/firecracker";processprovider "github.com/example-user/runnerhub/internal/providers/process";proxmoxprovider "github.com/example-user/runnerhub/internal/providers/proxmox";truenasprovider "github.com/example-user/runnerhub/internal/providers/truenas")
var version="dev"
func main(){ctx,stop:=signal.NotifyContext(context.Background(),syscall.SIGINT,syscall.SIGTERM);defer stop();name:=env("RUNNERHUB_HOST_NAME",hostname());kind:=env("RUNNERHUB_PROVIDER","docker");providers:=map[string]provider.Provider{};switch kind{case"docker":p,err:=dockerprovider.New(dockerprovider.Config{HostID:name,StateDir:env("RUNNERHUB_STATE_DIR","/var/lib/runnerhub"),AllowedImages:[]string{env("RUNNERHUB_RUNNER_IMAGE","ghcr.io/actions/actions-runner:latest")}});must(err);providers[kind]=p;case"process":p,err:=processprovider.New(processprovider.Config{HostID:name,RunnerDir:mustEnv("RUNNERHUB_RUNNER_DIR"),StateDir:env("RUNNERHUB_STATE_DIR","/var/lib/runnerhub/process")});must(err);providers[kind]=p;case"firecracker":p,err:=firecrackerprovider.New(firecrackerprovider.Config{HostID:name,KernelImage:mustEnv("RUNNERHUB_FIRECRACKER_KERNEL"),RootFS:mustEnv("RUNNERHUB_FIRECRACKER_ROOTFS"),Bridge:mustEnv("RUNNERHUB_FIRECRACKER_BRIDGE"),StateDir:env("RUNNERHUB_STATE_DIR","/var/lib/runnerhub/firecracker")});must(err);providers[kind]=p;case"proxmox":p,err:=proxmoxprovider.New(proxmoxprovider.Config{HostID:name,BaseURL:mustEnv("RUNNERHUB_PROXMOX_URL"),TokenID:mustEnv("RUNNERHUB_PROXMOX_TOKEN_ID"),TokenSecret:mustEnv("RUNNERHUB_PROXMOX_TOKEN_SECRET"),Node:mustEnv("RUNNERHUB_PROXMOX_NODE"),TemplateVMID:mustIntEnv("RUNNERHUB_PROXMOX_TEMPLATE_VMID"),SnippetDir:mustEnv("RUNNERHUB_PROXMOX_SNIPPET_DIR"),SnippetStore:env("RUNNERHUB_PROXMOX_SNIPPET_STORE","local")});must(err);providers[kind]=p;case"truenas":p,err:=truenasprovider.New(truenasprovider.Config{HostID:name,Root:env("RUNNERHUB_TRUENAS_ROOT","/mnt/Databases/containers/runnerhub"),AllowedImages:[]string{env("RUNNERHUB_RUNNER_IMAGE","ghcr.io/actions/actions-runner:latest")}});must(err);providers[kind]=p;default:log.Fatalf("unsupported provider %q",kind)};c,err:=agent.NewClient(agent.ClientConfig{ControlPlaneURL:mustEnv("RUNNERHUB_CONTROL_PLANE_URL"),EnrollmentToken:mustEnv("RUNNERHUB_ENROLLMENT_TOKEN"),Name:name,Provider:kind,AgentVersion:version,AllowInsecureHTTP:boolEnv("RUNNERHUB_ALLOW_INSECURE_HTTP",false)},providers);must(err);if err:=c.Run(ctx);err!=nil&&ctx.Err()==nil{log.Fatal(err)}}
func env(k,d string)string{if v:=os.Getenv(k);v!=""{return v};return d}
func mustEnv(k string)string{v:=os.Getenv(k);if v==""{log.Fatalf("%s is required",k)};return v}
func mustIntEnv(k string)int{v:=mustEnv(k);n,err:=strconv.Atoi(v);if err!=nil{log.Fatalf("%s must be an integer",k)};return n}
func boolEnv(k string,d bool)bool{v:=strings.TrimSpace(os.Getenv(k));if v==""{return d};b,err:=strconv.ParseBool(v);if err!=nil{log.Fatalf("%s must be true or false",k)};return b}
func hostname()string{h,_:=os.Hostname();return h}
func must(err error){if err!=nil{log.Fatal(err)}}
